if (tw.local.odcRequest.appInfo.status != tw.epv.RequestState.Canceled + "" && tw.local.odcRequest.appInfo.status != tw.epv.RequestState.Terminated + "") {
	if (tw.local.opreation_request_type == "" || tw.local.opreation_request_type == null) { }
	else {
		if (tw.local.odcRequest.requestType.name == tw.epv.RequestType.Create) {
			tw.local.fullPath = tw.env.FILENET_ROOT_PATH + "/" + tw.local.odcRequest.CustomerInfo.cif + "/DC Outward/" + tw.local.odcRequest.requestNo + "ODC" + "/Issuance";

		} else if (tw.local.odcRequest.requestType.value == "" + tw.epv.RequestType.Amendment) {

			tw.local.fullPath = tw.env.FILENET_ROOT_PATH + "/" + tw.local.odcRequest.cif + "/DC Outward/" + tw.local.odcRequest.parentRequestNo + " - " + tw.local.type + "/Liquidation " + tw.local.odcRequest.appInfo.instanceID;

		} else if (tw.local.odcRequest.requestType.value == "" + tw.epv.RequestType.Recreate) {

			tw.local.fullPath = tw.env.FILENET_ROOT_PATH + "/" + tw.local.odcRequest.CustomerInfo.cif + "/DC Outward/" + tw.local.odcRequest.parentRequestNo + "ODC" + "/Recreate " + tw.local.odcRequest.requestNo;



		} else if (tw.local.odcRequest.requestType.value == "" + tw.epv.RequestType.Collection) {


			tw.local.fullPath = tw.env.FILENET_ROOT_PATH + "/" + tw.local.odcRequest.CustomerInfo.cif + "/DC Outward/" + tw.local.odcRequest.parentRequestNo + "ODC" + "/Collection " + tw.local.odcRequest.requestNo;

		} else if (tw.local.odcRequest.requestType.value == "" + tw.epv.RequestType.Closure) {


			tw.local.fullPath = tw.env.FILENET_ROOT_PATH + "/" + tw.local.odcRequest.CustomerInfo.cif + "/DC Outward/" + tw.local.odcRequest.parentRequestNo + "ODC" + "/Closure " + tw.local.odcRequest.requestNo;

		}
		else if (tw.local.odcRequest.requestType.value == "" + tw.epv.RequestType.Reversal) {
			tw.local.fullPath = tw.env.FILENET_ROOT_PATH + "/" + tw.local.odcRequest.CustomerInfo.cif + "/DC Outward/" + tw.local.odcRequest.parentRequestNo + "ODC" + "/Reversal " + tw.local.odcRequest.requestNo;
		}

		else {
			tw.local.fullPath = tw.local.odcRequest.CustomerInfo.cif + "/DC Outward/" + tw.local.odcRequest.appInfo.instanceID + "ODC" + "/Canceled Cases"
			if (tw.local.odcRequest.requestType.name == tw.epv.RequestType.Create) {
				tw.local.fullPath +=  "/Issuance";
	
			} else if (tw.local.odcRequest.requestType.value == "" + tw.epv.RequestType.Amendment) {
	
				tw.local.fullPath += "/Liquidation " + tw.local.odcRequest.appInfo.instanceID;
	
			} else if (tw.local.odcRequest.requestType.value == "" + tw.epv.RequestType.Recreate) {
	
				tw.local.fullPath += "/Recreate " + tw.local.odcRequest.requestNo;
	
	
	
			} else if (tw.local.odcRequest.requestType.value == "" + tw.epv.RequestType.Collection) {
	
	
				tw.local.fullPath += "/Collection " + tw.local.odcRequest.requestNo;
	
			} else if (tw.local.odcRequest.requestType.value == "" + tw.epv.RequestType.Closure) {
	
	
				tw.local.fullPath += "/Closure " + tw.local.odcRequest.requestNo;
	
			}
			else if (tw.local.odcRequest.requestType.value == "" + tw.epv.RequestType.Reversal) {
				tw.local.fullPath +="/Reversal " + tw.local.odcRequest.requestNo;
			}
		}
	}
}

